  const contextStateLabel = dashboardTimeContextActive && dashboardSelectedTimeSec !== null
    ? " · " + formatTimeTravel(dashboardSelectedTimeSec)
    : !dashboardTimeContextActive && selectedTimeSec !== null
      ? " · " + formatTimeTravel(selectedTimeSec)
      : contextPaused
        ? " · display frozen"
        : isLatestAvailable
          ? " · latest available"
          : !summary.updatedAt
            ? " · waiting for data"
            : "";
  const contextUpdatedLabel = "Updated " + (summary.updatedAt ? formatRelativeTime(summary.updatedAt) : "waiting") + contextStateLabel;
  const liveLabel = dashboardTimeContextActive && dashboardSelectedTimeSec !== null
    ? "Time travel"
    : !dashboardTimeContextActive && selectedTimeSec !== null
      ? "Time travel"
      : contextPaused
        ? "Paused"
        : isLatestAvailable
          ? "Latest available"
          : summary.updatedAt
            ? "Live"
            : "Waiting";
  const liveTone = isLatestAvailable || contextTimeSec !== null || contextPaused || !summary.updatedAt ? "warning" as const : "success" as const;
  const toggleTheme = () => setTheme((current) => (current === "light" ? "dark" : "light"));
  const toggleLive = () => dashboardTimeContextActive
    ? dashboardLocalTimeSec !== null || dashboardPaused || isLatestAvailable ? resumeDashboardLive() : pauseDashboardLive()
    : selectedTimeSec !== null || paused || isLatestAvailable ? resumeLiveTime() : setPaused((current) => !current);

  const renderStatusHeader = (title: string, icon: IconName) => (
    <AppContextBar
      compact
      title={title}
      icon={icon}
      updatedLabel={contextUpdatedLabel}
      socketState={socketState}
      liveLabel={liveLabel}
      liveTone={liveTone}
      onToggleLive={toggleLive}
      onToggleTheme={toggleTheme}
      theme={theme}
    />
  );

  const renderStandaloneSearch = (placeholder: string) => (
    <SearchInput className="standalone-search" value={query} onChange={setQuery} placeholder={placeholder} label="search" />
  );

  const selectGlobalTime = (timeSec: number) => {
    setSelectedTimeSec(timeSec);
    setPaused(true);
    setTimelineFollowNow(false);
    setManualTimelineWindowEndSec(timeSec);
  };

  const resumeLiveTime = () => {
    setSelectedTimeSec(null);
    setPaused(false);
    setTimelineFollowNow(true);
    setManualTimelineWindowEndSec(null);
  };

  const selectDashboardTime = (timeSec: number) => {
    setDashboardSelectedTimeSec(timeSec);
    setDashboardPaused(false);
    setDashboardPauseTimeSec(null);
  };
  const pauseDashboardLive = () => {
    setDashboardSelectedTimeSec(null);
    setDashboardPaused(true);
    setDashboardPauseTimeSec(summary.updatedAt ?? Date.now() / 1000);
  };
  const resumeDashboardLive = () => {
    setDashboardSelectedTimeSec(null);
    setDashboardPaused(false);
    setDashboardPauseTimeSec(null);
  };

  const dashboardLayout = dashboardLayouts.find((layout) => layout.id === dashboardLayoutId) ?? dashboardLayouts[0] ?? DEFAULT_DASHBOARD_LAYOUT;
  const dashboardContextLabel = dashboardSelectedTimeSec !== null ? formatTimeTravel(dashboardSelectedTimeSec) : dashboardPaused ? "Paused" : latestAvailableTimeSec !== null ? "Latest available" : summary.updatedAt ? "Live" : "Waiting";

  const updateDashboardCell = (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => layout.id !== dashboardLayout.id ? layout : {
      ...layout,
      cells: layout.cells.map((cell) => cell.id === cellId ? clampDashboardCell(updater(cell), layout.columns) : cell),
      layouts: layout.layouts ? Object.fromEntries(
        (Object.entries(layout.layouts) as [DashboardBreakpoint, DashboardCell[]][]).map(([breakpoint, cells]) => [
          breakpoint,
          cells.map((cell) => cell.id === cellId ? updater(cell) : cell)
        ])
      ) as DashboardResponsiveLayouts : undefined
    }));
  };

  const updateDashboardCellParams = (cellId: string, params: Record<string, string>) => {
    updateDashboardCell(cellId, (cell) => ({ ...cell, params: { ...cell.params, ...params } }));
  };

  const renderDashboardCellActions = (cell: DashboardCell) => {
    const query = dashboardCellTextParam(cell, "query");
    if (cell.viewType === "streams") {
      return <SearchInput className="dashboard-cell-search" value={query} onChange={(value) => updateDashboardCellParams(cell.id, { query: value })} placeholder="Filter streams" label="filter streams" />;
    }
    if (cell.viewType === "detail") {
      const mode = dashboardDetailMode(cell);
      return <div className="detail-mode-tabs" role="tablist" aria-label="Detail mode">
        <button type="button" className={mode === "overview" ? "active" : ""} onClick={() => updateDashboardCellParams(cell.id, { detailMode: "overview" })}>Overview</button>
        <button type="button" className={mode === "detail" ? "active" : ""} onClick={() => updateDashboardCellParams(cell.id, { detailMode: "detail" })}>Detail</button>
      </div>;
    }
    if (cell.viewType === "events") {
      const tab = dashboardEventsTab(cell);
      return <>
        <SearchInput className="dashboard-cell-search" value={query} onChange={(value) => updateDashboardCellParams(cell.id, { query: value })} placeholder="Search events" label="search events" />
        <div className="events-tabs" role="tablist" aria-label="Event scope">
          <button type="button" className={tab === "all" ? "active" : ""} onClick={() => updateDashboardCellParams(cell.id, { eventsTab: "all" })}>All</button>
          <button type="button" className={tab === "selected" ? "active" : ""} onClick={() => updateDashboardCellParams(cell.id, { eventsTab: "selected" })}>Selected</button>
        </div>
      </>;
    }
    return null;
  };

  const addDashboardCell = () => {
    const id = `cell-${Date.now().toString(36)}`;
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => {
      if (layout.id !== dashboardLayout.id) return layout;
      const cell = { id, title: "Topology", viewType: "topology" as DashboardViewType, grid: { x: 0, y: nextDashboardY(layout.cells), w: 8, h: 8 } };
      const responsiveLayouts = layout.layouts ? Object.fromEntries(
        (Object.entries(layout.layouts) as [DashboardBreakpoint, DashboardCell[]][]).map(([breakpoint, cells]) => {
          const columns = breakpoint === "mobile" ? 4 : breakpoint === "tablet" ? 12 : 24;
          return [breakpoint, [...cells, { ...cell, grid: { x: 0, y: nextDashboardY(cells), w: Math.min(cell.grid.w, columns), h: cell.grid.h } }]];
        })
      ) as DashboardResponsiveLayouts : undefined;
      return { ...layout, cells: [...layout.cells, cell], layouts: responsiveLayouts };
    }));
  };

  const removeDashboardCell = (cellId: string) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => layout.id !== dashboardLayout.id ? layout : {
      ...layout,
      cells: layout.cells.filter((cell) => cell.id !== cellId),
      layouts: layout.layouts ? Object.fromEntries(
        Object.entries(layout.layouts).map(([breakpoint, cells]) => [breakpoint, cells.filter((cell) => cell.id !== cellId)])
      ) as DashboardResponsiveLayouts : undefined
    }));
  };

  const resetDashboardLayout = () => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => {
      const retained = layouts.filter((layout) => layout.id !== DEFAULT_DASHBOARD_LAYOUT.id);
      return [DEFAULT_DASHBOARD_LAYOUT, ...retained];
    });
    setDashboardLayoutId(DEFAULT_DASHBOARD_LAYOUT.id);
  };

  const saveDashboardLayout = async () => {
    setDashboardSaveState("saving");
    try {
      const saved = await saveDashboardLayouts(dashboardLayouts);
      setDashboardLayouts(saved.length > 0 ? saved : [DEFAULT_DASHBOARD_LAYOUT]);
      setDashboardSaveState("saved");
    } catch {
      setDashboardSaveState("error");
    }
  };

  const updateDashboardLayouts = (nextLayouts: DashboardResponsiveLayouts) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => {
      if (layout.id !== dashboardLayout.id) return layout;
      const desktop = nextLayouts.desktop ?? layout.cells;
      return { ...layout, cells: desktop, layouts: nextLayouts };
    }));
  };

  const renderDashboardView = () => (
    <section className="main-tab-view dashboard-view">
      <PaneHeader
        className="dashboard-toolbar"
        icon="dashboard"
        title="Dashboard"
        meta={dashboardContextLabel + " · " + dashboardLayout.cells.length + " cells / " + dashboardLayout.columns + " columns"}
        actions={<div className="dashboard-actions">
          <label className="detail-range-select dashboard-time-range">
            <span>Range</span>
            <select value={dashboardRange} onChange={(event) => setDashboardRange(event.target.value)}>
              {RANGE_OPTIONS.map((range) => <option key={range} value={range}>{range}</option>)}
            </select>
          </label>
          <label className="detail-range-select">
            <span>Layout</span>
            <select value={dashboardLayout.id} onChange={(event) => setDashboardLayoutId(event.target.value)}>
              {dashboardLayouts.map((layout) => <option key={layout.id} value={layout.id}>{layout.name}</option>)}
            </select>
          </label>
          <button type="button" className={`dashboard-action-button button-with-icon ${dashboardEditing ? "primary" : ""}`} onClick={() => setDashboardEditing((editing) => !editing)}>
            {dashboardEditing ? <><Icon name="done" size={15} />Done</> : <><Icon name="edit" size={15} />Edit layout</>}
          </button>
          {dashboardEditing && <>
            <button type="button" className="dashboard-action-button button-with-icon" onClick={addDashboardCell}><Icon name="add" size={15} />Add cell</button>
            <button type="button" className="dashboard-action-button button-with-icon" onClick={resetDashboardLayout}><Icon name="reset" size={15} />Reset</button>
            <button type="button" className="dashboard-action-button button-with-icon primary" onClick={() => void saveDashboardLayout()} disabled={dashboardSaveState === "saving"}>
              <Icon name={dashboardSaveState === "saved" ? "done" : "save"} size={15} />{dashboardSaveState === "saving" ? "Saving" : dashboardSaveState === "saved" ? "Saved" : dashboardSaveState === "error" ? "Retry save" : "Save"}
            </button>
          </>}
        </div>}
      />
      <div className="dashboard-pane-body">
        <DashboardGrid
          dashboard={dashboardLayout}
          editing={dashboardEditing}
          renderCell={renderDashboardCellContent}
          renderCellActions={renderDashboardCellActions}
          onLayoutsChange={updateDashboardLayouts}
          onUpdateCell={updateDashboardCell}
          onRemoveCell={removeDashboardCell}
        />
      </div>
    </section>
  );

  const renderDashboardCellContent = (cell: DashboardCell) => {
    const viewType = cell.viewType;
    if (viewType === "streams") {
      return <StreamTable
        streams={filterStreams(streams, dashboardCellTextParam(cell, "query"))}
        interfaces={interfaces}
        selectedStreamKey={selectedStreamKey}
        selectedFlowKey={selectedFlowKey}
        selectedInterfaceKey={selectedInterfaceKey}
        overviewMode
        expandLevel={expandLevel}
        onSelectInterface={(interfaceKey) => {
          setSelectedInterfaceKey(interfaceKey);
          setSelectedStreamKey(null);
          setSelectedFlowKey(null);
        }}
        onSelectStream={(streamKey) => {
          setSelectedInterfaceKey(null);
          setSelectedStreamKey(streamKey);
          setSelectedFlowKey(null);
        }}
        onSelectFlow={(streamKey, flowKey) => {
          setSelectedInterfaceKey(null);
          setSelectedStreamKey(streamKey);
          setSelectedFlowKey(flowKey);
        }}
      />;
    }
    if (viewType === "detail") {
      return selectedInterface && !selectedStreamKey ? <InterfaceDetailPane
        item={selectedInterface}
        metrics={selectedInterfaceMetrics}
        metrics={selectedInterfaceMetrics}
        mode={dashboardDetailMode(cell)}
        onChangeMode={(mode) => updateDashboardCellParams(cell.id, { detailMode: mode })}
        onMinimizeWidth={() => undefined}
        onRestoreWidth={() => undefined}
        onMaximizeWidth={() => undefined}
        isWidthMinimized={false}
        isWidthRestored
        isWidthMaximized
        showWidthControls={false}
        embedded
      /> : <DetailPane
        stream={detailStream}
        metrics={selectedMetrics}
        selectedFlowKey={selectedFlowKey}
        metricsRange={dashboardRange}
        onChangeMetricsRange={setDashboardRange}
        mode={dashboardDetailMode(cell)}
        onChangeMode={(mode) => updateDashboardCellParams(cell.id, { detailMode: mode })}
        onMinimizeWidth={() => undefined}
        onRestoreWidth={() => undefined}
        onMaximizeWidth={() => undefined}
        isWidthMinimized={false}
        isWidthRestored
        isWidthMaximized
        showWidthControls={false}
        embedded
      />;
    }
    if (viewType === "timeline") {
      return (
        <div className="timeline-body dashboard-timeline-body">
          <TimelinePane
            rows={timeline}
            nowSec={dashboardContextTimeSec ?? summary.updatedAt ?? Date.now() / 1000}
            fadeSec={appConfig.lostRetentionSec}
            rangeStartSec={timelineWindow.from}
            rangeEndSec={timelineWindow.to}
            expandLevel={timelineExpandLevel}
            selectedTimeSec={dashboardContextTimeSec}
            onSelectTime={selectDashboardTime}
            interfaceNames={timelineInterfaceNames}
          />
        </div>
      );
    }
    if (viewType === "topology") return <TopologyPane
      selectedTimeSec={dashboardContextTimeSec}
      filterQuery=""
      onSelectStream={(streamKey) => {
        setSelectedInterfaceKey(null);
        setSelectedStreamKey(streamKey);
        setSelectedFlowKey(null);
      }}
      onSelectFlow={(streamKey, flowKey) => {
        setSelectedInterfaceKey(null);
        setSelectedStreamKey(streamKey);
        setSelectedFlowKey(flowKey);
      }}
      onSelectTime={selectDashboardTime}
    />;
    return <EventLog
      events={events}
      eventsRange={dashboardRange}
      onChangeEventsRange={setDashboardRange}
      query={dashboardCellTextParam(cell, "query")}
      onChangeQuery={(value) => updateDashboardCellParams(cell.id, { query: value })}
      showSearch={false}
      showHeader={false}
      tab={dashboardEventsTab(cell)}
      onChangeTab={(tab) => updateDashboardCellParams(cell.id, { eventsTab: tab })}
      selectedStreamKey={selectedStreamKey}
      selectedFlowKey={selectedFlowKey}
      selectedInterfaceId={selectedInterface?.interfaceId ?? null}
      selectedTimeSec={dashboardContextTimeSec}
      onSelectTime={selectDashboardTime}
    />;
  };

  if (standaloneView) {
    const detailStreamForStandalone: StreamState | null = selectedStream ?? (selectedListItem
      ? {
          ...selectedListItem,
          flows: selectedListItem.flows.map((flow) => ({
            ...flow,
            metrics: {}
          }))
        }
      : null);

    return (
      <main className="app-shell standalone-shell" aria-busy={loading}>
        {loading && (
          <div className="loading-overlay" role="status" aria-live="polite" aria-label="Loading">
            <div className="loading-card">
              <span className="loading-label">Loading...</span>
              <span className="loading-subtext">Waiting for initial stream snapshot</span>
            </div>
          </div>
        )}
        {standaloneView === "streams" && (
          <section className="standalone-view standalone-streams">
            {renderStatusHeader("Streams", "streams")}
            <div className="list-toolbar standalone-toolbar">
              <div className="list-toolbar-header">
                <div>
                  <h2>Active Streams</h2>
                  <p>{filteredStreams.length} visible / {streams.length} total</p>
                </div>
                <div className="list-toolbar-actions">
{/*
                  <button type="button" className="list-sort-refresh-button" onClick={() => setStreamSortRefreshToken((value) => value + 1)}>
                    Sort refresh
                  </button>
*/}
                  <div className="expand-level-controls" role="tablist" aria-label="Tree expand level">
                    <button type="button" className={expandLevel === "interface" ? "active" : ""} onClick={() => setExpandLevel("interface")} aria-pressed={expandLevel === "interface"}>NIC</button>
                    <button type="button" className={expandLevel === "proto" ? "active" : ""} onClick={() => setExpandLevel("proto")} aria-pressed={expandLevel === "proto"}>Proto</button>
                    <button type="button" className={expandLevel === "stream" ? "active" : ""} onClick={() => setExpandLevel("stream")} aria-pressed={expandLevel === "stream"}>Stream</button>
                    <button type="button" className={expandLevel === "flow" ? "active" : ""} onClick={() => setExpandLevel("flow")} aria-pressed={expandLevel === "flow"}>Flow</button>
                  </div>
                </div>
              </div>
              {renderStandaloneSearch("Filter streams")}
            </div>
            <StreamTable
              streams={filteredStreams}
              interfaces={interfaces}
              selectedStreamKey={selectedStreamKey}
              selectedFlowKey={selectedFlowKey}
              selectedInterfaceKey={selectedInterfaceKey}
              overviewMode
              expandLevel={expandLevel}
              onSelectInterface={setSelectedInterfaceKey}
              onSelectStream={setSelectedStreamKey}
              onSelectFlow={(streamKey, flowKey) => {
                setSelectedStreamKey(streamKey);
                setSelectedFlowKey(flowKey);
              }}
            />
          </section>
        )}
        {standaloneView === "timeline" && (
          <section className="standalone-view standalone-timeline">
            {renderStatusHeader("Timeline", "timeline")}
            <div className="timeline-header standalone-toolbar">
              <h3>Timeline</h3>
<div className="list-toolbar-actions">
              <div className="expand-level-controls" role="tablist" aria-label="Timeline expand level">
                <button type="button" className={timelineExpandLevel === "interface" ? "active" : ""} onClick={() => setTimelineExpandLevel("interface")} aria-pressed={timelineExpandLevel === "interface"}>NIC</button>
                <button type="button" className={timelineExpandLevel === "proto" ? "active" : ""} onClick={() => setTimelineExpandLevel("proto")} aria-pressed={timelineExpandLevel === "proto"}>Proto</button>
                <button type="button" className={timelineExpandLevel === "stream" ? "active" : ""} onClick={() => setTimelineExpandLevel("stream")} aria-pressed={timelineExpandLevel === "stream"}>Stream</button>
                <button type="button" className={timelineExpandLevel === "flow" ? "active" : ""} onClick={() => setTimelineExpandLevel("flow")} aria-pressed={timelineExpandLevel === "flow"}>Flow</button>
              </div>
              <label className="detail-range-select timeline-range-select">
                <span>Range</span>
                <select
                  value={timelineRange}
                  onChange={(event) => {
                    setTimelineRange(event.target.value);
                    if (timelineFollowNow) setManualTimelineWindowEndSec(null);
                  }}
                >
                  {RANGE_OPTIONS.map((range) => <option key={range} value={range}>{range}</option>)}
                </select>
              </label>
{/*
              <button type="button" className="list-sort-refresh-button" onClick={() => setTimelineSortRefreshToken((value) => value + 1)}>
                Sort refresh
              </button>
*/}
              {renderStandaloneSearch("Filter timeline")}
            </div>
            </div>
            <div ref={timelineBodyRef} className="timeline-body standalone-body" title="Ctrl + Wheel: move timeline window">
              {timelineLoading && (
                <div className="timeline-loading-overlay" role="status" aria-live="polite" aria-label="Loading timeline">
                  <div className="timeline-loading-dialog">
                    <div className="timeline-loading-spinner" />
                    <span>Loading timeline...</span>
                  </div>
                </div>
              )}
              <TimelinePane
                rows={filteredTimeline}
                nowSec={tabContextTimeSec ?? summary.updatedAt ?? Date.now() / 1000}
                fadeSec={appConfig.lostRetentionSec}
                rangeStartSec={timelineWindow.from}
                rangeEndSec={timelineWindow.to}
                expandLevel={timelineExpandLevel}
                selectedTimeSec={tabContextTimeSec}
                onSelectTime={selectGlobalTime}
                interfaceNames={timelineInterfaceNames}
              />
            </div>
          </section>
        )}
        {standaloneView === "events" && (
          <section className="standalone-view standalone-events">
            {renderStatusHeader("Events", "events")}
            <EventLog
              events={events}
                eventsRange={eventsRange}
                onChangeEventsRange={setEventsRange}
                selectedStreamKey={selectedStreamKey}
                selectedFlowKey={selectedFlowKey}
                selectedInterfaceId={selectedInterface?.interfaceId ?? null}
                selectedTimeSec={tabContextTimeSec}
                onSelectTime={selectGlobalTime}
                initialQuery={query}
            />
          </section>
        )}
        {standaloneView === "detail" && (
          <section className="standalone-view standalone-detail">
            {renderStatusHeader("Detail", "detail")}
            {selectedInterface && !selectedStreamKey ? (
              <InterfaceDetailPane
                item={selectedInterface}
                metrics={selectedInterfaceMetrics}
                mode={detailMode}
                onChangeMode={setDetailMode}
                onMinimizeWidth={() => undefined}
                onRestoreWidth={() => undefined}
                onMaximizeWidth={() => undefined}
                isWidthMinimized={false}
                isWidthRestored
                isWidthMaximized
                showWidthControls={false}
              />
            ) : (
              <DetailPane
                stream={detailStreamForStandalone}
                metrics={selectedMetrics}
                selectedFlowKey={selectedFlowKey}
                metricsRange={metricsRange}
                onChangeMetricsRange={setMetricsRange}
                mode={detailMode}
                onChangeMode={setDetailMode}
                onMinimizeWidth={() => undefined}
                onRestoreWidth={() => undefined}
                onMaximizeWidth={() => undefined}
                isWidthMinimized={false}
                isWidthRestored
                isWidthMaximized
                showWidthControls={false}
              />
            )}
          </section>
        )}
      </main>
    );
  }

  return (
    <main className="app-shell" aria-busy={loading}>
      {loading && (
        <div className="loading-overlay" role="status" aria-live="polite" aria-label="Loading">
          <div className="loading-card">
            <span className="loading-label">Loading...</span>
            <span className="loading-subtext">Waiting for initial stream snapshot</span>
          </div>
        </div>
      )}
      <div className="app-frame">
        <aside className={`menu-rail ${menuExpanded ? "expanded" : "collapsed"}`}>
          <button
            type="button"
            className="menu-rail-toggle"
            onClick={() => setMenuExpanded((current) => !current)}
            aria-pressed={menuExpanded}
            aria-label={menuExpanded ? "Collapse menu" : "Expand menu"}
            title={menuExpanded ? "Collapse menu" : "Expand menu"}
          >
            <span className="menu-rail-toggle-icon"><Icon name={menuExpanded ? "menuCollapse" : "menuExpand"} size={18} /></span>
            {menuExpanded && <span className="menu-rail-brand">MSM</span>}
          </button>
          <nav className="menu-rail-nav" aria-label="Primary">
            {MENU_ITEMS.map((item) => (
              <button
                key={item.key}
                type="button"
                className={`menu-item ${item.key === activeTab ? "active" : ""}`}
                title={item.label}
                onClick={() => setActiveTab(item.key)}
                aria-pressed={item.key === activeTab}
              >
                <span className="menu-item-icon"><Icon name={item.icon} size={20} /></span>
                {menuExpanded && (
                  <span className="menu-item-copy">
                    <strong>{item.label}</strong>
                    <small>{item.hint}</small>
                  </span>
                )}
              </button>
            ))}
          </nav>
        </aside>

        <div className="app-main">
          <AppContextBar
            updatedLabel={contextUpdatedLabel}
            socketState={socketState}
            totalStreams={summary.totalStreams}
            liveLabel={liveLabel}
            liveTone={liveTone}
            onToggleLive={toggleLive}
            onToggleTheme={toggleTheme}
            theme={theme}
          />

          {activeTab === "dashboard" ? renderDashboardView() : (
            <section className={`main-tab-view main-tab-${activeTab}`}> 
              {activeTab === "streams" && (
                <PaneFrame
                  className="streams-tab-frame"
                  header={<PaneHeader
                    title="Streams"
                    icon="streams"
                    meta="Active stream list"
                    actions={<div className="pane-header-actions stream-tab-actions">
                      <SearchInput className="pane-search" value={query} onChange={setQuery} placeholder="Filter streams" label="stream search" />
                      <div className="expand-level-controls" role="tablist" aria-label="Tree expand level">
                        <button type="button" className={expandLevel === "interface" ? "active" : ""} onClick={() => setExpandLevel("interface")}>NIC</button>
                        <button type="button" className={expandLevel === "proto" ? "active" : ""} onClick={() => setExpandLevel("proto")}>Proto</button>
                        <button type="button" className={expandLevel === "stream" ? "active" : ""} onClick={() => setExpandLevel("stream")}>Stream</button>
                        <button type="button" className={expandLevel === "flow" ? "active" : ""} onClick={() => setExpandLevel("flow")}>Flow</button>
                      </div>
                    </div>}
                  />}
                >
                  <StreamTable
                    streams={filteredStreams}
                    interfaces={interfaces}
                    selectedStreamKey={selectedStreamKey}
                    selectedFlowKey={selectedFlowKey}
                    selectedInterfaceKey={selectedInterfaceKey}
                    overviewMode
                    expandLevel={expandLevel}
                    onSelectInterface={(interfaceKey) => {
                      setSelectedInterfaceKey(interfaceKey);
                      setSelectedStreamKey(null);
                      setSelectedFlowKey(null);
                    }}
                    onSelectStream={(streamKey) => {
                      setSelectedInterfaceKey(null);
                      setSelectedStreamKey(streamKey);
                      setSelectedFlowKey(null);
                    }}
                    onSelectFlow={(streamKey, flowKey) => {
                      setSelectedInterfaceKey(null);
                      setSelectedStreamKey(streamKey);
                      setSelectedFlowKey(flowKey);
                    }}
                  />
                </PaneFrame>
              )}
              {activeTab === "detail" && (
                <section className="standalone-view standalone-detail">
                  {selectedInterface && !selectedStreamKey ? (
                    <InterfaceDetailPane
                      item={selectedInterface}
                      metrics={selectedInterfaceMetrics}
                      mode={detailMode}
