item.aggregated_output:
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { FlowListItem, InterfaceListItem, StreamListItem } from "../types/api";
import { Sparkline } from "./Sparkline";
import { Icon } from "./ui/Icon";
import { formatBitrate, formatRelativeTime } from "./format";

type StreamTableProps = {
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceKey: string | null;
  overviewMode?: boolean;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  onSelectInterface: (interfaceKey: string) => void;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
};

const TOTAL_COLOR = "#66d9ef";
const FLOW_ROLE_COLORS: Record<string, string> = {
  media: "#7fd4c7",
  fec_row: "#62b7c3",
  fec_col: "#6e97c7",
  control: "#5f7fb9",
  mixed: "#6fa7d4",
  default: "#7f98b5"
};
const FLOW_ROLE_LINE_COLORS: Record<string, string> = {
  media: "#9ae2d7",
  fec_row: "#7cc7d1",
  fec_col: "#87abd5",
  control: "#7695cb",
  mixed: "#8bb8de",
  default: "#97acc3"
};
const DONUT_COLORS = ["#66d9ef", "#7fd4c7", "#6e97c7", "#62b7c3", "#8bb8de", "#7f98b5"];
const ENABLE_FLIP_ANIMATION = false;
const ENABLE_SPARKLINES = true;
const ENABLE_OVERVIEW_STATS = true;
const ENABLE_OVERVIEW_CHARTS = false;
const MAX_STREAM_ROWS_PER_GROUP = 200;
const MAX_FLOW_ROWS_PER_STREAM = 80;
const STREAM_TABLE_OVERSCAN_PX = 600;
const STREAM_TABLE_ROW_HEIGHT = {
//  interface: 58,
//  interface: 44,
//  interface: 46,
  interface: 47,
//  proto: 52,
//  proto: 50,
  proto: 48,
//  proto: 50,
//  stream: 66,
//  stream: 55,
  stream: 47,
//  flow: 46,
//  flow: 55,
  flow: 47,
  truncated: 34
};

type InterfaceGroup = {
  key: string;
  name: string;
  interfaceItem?: InterfaceListItem;
  streams: StreamListItem[];
};

type FlatRow =
  | { key: string; type: "interface"; height: number; group: InterfaceGroup }
  | { key: string; type: "proto"; height: number; group: { key: string; proto: string; streams: StreamListItem[] } }
  | { key: string; type: "stream"; height: number; stream: StreamListItem }
  | { key: string; type: "flow"; height: number; stream: StreamListItem; flow: FlowListItem }
  | { key: string; type: "truncated"; height: number; label: string; depth: "stream" | "flow" };

export function StreamTable({ streams, interfaces, selectedStreamKey, selectedFlowKey, selectedInterfaceKey, overviewMode = false, expandLevel = "flow", onSelectInterface, onSelectStream, onSelectFlow }: StreamTableProps) {
  const tableRef = useRef<HTMLDivElement>(null);
  const scrollingRef = useRef(false);
  const scrollIdleTimerRef = useRef<number | null>(null);
  const scrollRafRef = useRef<number | null>(null);
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [expandedInterfaces, setExpandedInterfaces] = useState<Set<string>>(() => new Set());
  const [expandedProtoGroups, setExpandedProtoGroups] = useState<Set<string>>(() => new Set());
  const [viewport, setViewport] = useState({ top: 0, height: 640 });
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);
  const previousRects = useRef(new Map<string, DOMRect>());
  const seenProtoGroupKeys = useRef<Set<string>>(new Set());
  const maxStreamBitrate = useMemo(() => Math.max(...streams.map(streamBitrateOf), 1), [streams]);
  const interfaceGroups = useMemo(() => buildInterfaceGroups(interfaces, streams), [interfaces, streams]);
  const groupedByInterface = interfaceGroups.length > 0;

  useEffect(() => {
    if (hasAppliedExpandLevel.current && previousExpandLevel.current === expandLevel) {
      return;
    }
    previousExpandLevel.current = expandLevel;
    setExpandedInterfaces(expandedInterfaceKeys(interfaceGroups, expandLevel));
    setExpanded(expandedStreamKeys(streams, expandLevel));
    setExpandedProtoGroups(expandedProtoKeys(interfaceGroups, streams, expandLevel));
    if (interfaceGroups.length > 0 || streams.length > 0) {
      hasAppliedExpandLevel.current = true;
    }
  }, [expandLevel, interfaceGroups, streams]);

  useEffect(() => {
    if (expandLevel !== "stream" && expandLevel !== "flow") return;
    const keys = groupedByInterface
      ? interfaceGroups.flatMap((group) => buildProtoGroups(group.streams, group.key).map((protoGroup) => protoGroup.key))
      : buildProtoGroups(streams, "root").map((protoGroup) => protoGroup.key);
    if (keys.length === 0) return;
    setExpandedProtoGroups((current) => {
      const next = new Set(current);
      for (const key of keys) {
        if (!seenProtoGroupKeys.current.has(key)) {
          next.add(key);
          seenProtoGroupKeys.current.add(key);
        }
      }
      return next;
    });
  }, [expandLevel, groupedByInterface, interfaceGroups, streams]);

  useLayoutEffect(() => {
    if (!ENABLE_FLIP_ANIMATION) {
      return;
    }
    const root = tableRef.current;
    if (!root) return;

    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const nodes = Array.from(root.querySelectorAll<HTMLElement>("[data-flip-key]"));
    const disableFlip = !ENABLE_FLIP_ANIMATION || reduceMotion || scrollingRef.current || nodes.length > 220;
    const nextRects = new Map<string, DOMRect>();
    if (!disableFlip) {
      for (const node of nodes) {
        const key = node.dataset.flipKey;
        if (!key) continue;
        nextRects.set(key, node.getBoundingClientRect());
      }
      for (const node of nodes) {
        const key = node.dataset.flipKey;
        if (!key) continue;
        const prev = previousRects.current.get(key);

    const topPad = startIndex > 0 ? offsets[startIndex] : 0;
    const bottomPad = Math.max(0, total - (endIndex > 0 ? offsets[endIndex - 1] + flatRows[endIndex - 1].height : 0));

    return {
      topPad,
      bottomPad,
      visible: flatRows.slice(startIndex, endIndex)
    };
  }, [flatRows, viewport]);

  const renderStreamRow = (stream: StreamListItem) => {
    const expandable = isExpandable(stream);
    const opened = expanded.has(stream.streamKey);
    const streamBitrate = streamBitrateOf(stream);

    return (
      <div className="stream-tree stream-tree-virtual" data-flip-key={`stream:${stream.streamKey}`}>
        <button
          className={`stream-row ${stream.streamKey === selectedStreamKey && !selectedFlowKey ? "selected" : ""}`}
          onClick={() => selectStream(stream)}
        >
          <span className={`tree-toggle ${expandable ? "expandable" : ""} ${opened ? "open" : ""}`} onClick={(event) => { event.stopPropagation(); if (expandable) toggleStream(stream.streamKey); }}>
            {/* {expandable ? "›" : ""} */}
            {expandable && <Icon name="expand" size={15} />}
          </span>
          <span className={`status-dot ${stream.active ? "active" : "stale"}`} />
          <span className="stream-main">
            <span className="stream-title">
              <strong style={{ color: protoAccentColor(stream.kind) }}>{stream.kind}</strong>
              <span>{stream.label}</span>
            </span>
            <span className="stream-subtitle">
              {stream.interfaceName ? `if: ${stream.interfaceName} / ` : ""}
              {stream.flowCount} flow{stream.flowCount === 1 ? "" : "s"}
              {stream.flowRoles.length > 0 ? ` / ${stream.flowRoles.join(", ")}` : ""}
              {" / "}{formatRelativeTime(stream.lastSeen)}
              <CopyButton                title="Copy standalone detail URL"
                value={detailUrlForStream(stream.streamKey)}
              />
              <CopyButton                title="Copy streamKey"
                value={stream.streamKey}
              />
            </span>
          </span>
          <span className="row-right stream-row-right">
            <span className="stream-rate">{formatBitrate(streamBitrate)}</span>
            {overviewMode && <BitrateShareBar value={streamBitrate} max={maxStreamBitrate} />}
            {ENABLE_SPARKLINES && <Sparkline values={stream.sparkline} width={150} height={24} color={protoAccentColor(stream.kind)} strokeWidth={1.1} />}
            {overviewMode && ENABLE_OVERVIEW_STATS && <OverviewStats stats={stream.overview} />}
          </span>
        </button>
      </div>
    );
  };

  const renderProtoRow = (protoGroup: { key: string; proto: string; streams: StreamListItem[] }) => {
    const opened = expandedProtoGroups.has(protoGroup.key);
    const active = protoGroup.streams.some((stream) => stream.active);
    const bitrate = protoGroup.streams.reduce((sum, stream) => sum + streamBitrateOf(stream), 0);
    const sparkline = sumSparklines(protoGroup.streams.map((stream) => stream.sparkline));
    return (
      <div className="proto-tree proto-tree-virtual" data-flip-key={`proto:${protoGroup.key}`}>
        <button className="proto-row" onClick={(event) => { event.preventDefault(); toggleProtoGroup(protoGroup.key); }}>
          <span className={`tree-toggle expandable ${opened ? "open" : ""}`}><Icon name="expand" size={15} /></span>
          <span className={`proto-status ${active ? "active" : "stale"}`} />
          <span className="proto-main">
            <span className="proto-title">
              <strong>{protoGroup.proto}</strong>
              <span>{protoGroup.streams.length} stream{protoGroup.streams.length === 1 ? "" : "s"}</span>
            </span>
          </span>
          <span className="row-right proto-row-right">
            <span className="stream-rate">{formatBitrate(bitrate)}</span>
            {ENABLE_SPARKLINES && <Sparkline values={sparkline} width={150} height={24} color="#9aa9b8" strokeWidth={1.1} />}
          </span>
        </button>
      </div>
    );
  };

  const renderInterfaceRow = (group: InterfaceGroup) => {
    const opened = expandedInterfaces.has(group.key);
    return (
      <div className="interface-tree interface-tree-virtual" data-flip-key={`interface:${group.key}`}>
        <button className={`interface-row ${group.interfaceItem?.key === selectedInterfaceKey ? "selected" : ""}`} onClick={() => {
          if (group.interfaceItem) onSelectInterface(group.interfaceItem.key);
        }}>
          <span className={`tree-toggle expandable ${opened ? "open" : ""}`} onClick={(event) => { event.stopPropagation(); toggleInterface(group.key); }}><Icon name="expand" size={15} /></span>
          <span className={`interface-status ${group.interfaceItem?.available !== false ? "active" : "stale"}`} />
          <span className="interface-main">
            <span className="interface-title"><strong>{group.name}</strong><span>{group.streams.length} stream{group.streams.length === 1 ? "" : "s"}</span></span>
            <span className="interface-subtitle">{formatLinkSummary(group.interfaceItem)} / rx {formatBitrate(interfaceBitrateOf(group.interfaceItem, "rx"))} / tx {formatBitrate(interfaceBitrateOf(group.interfaceItem, "tx"))}</span>
          </span>
          {ENABLE_OVERVIEW_CHARTS && <InterfaceHeadroomGauge item={group.interfaceItem} />}
          <span className="interface-sparklines">
            <span className="interface-rate-row">
              <span className="interface-rate-label">RX</span>
              <span className="interface-rate-value">{formatBitrate(interfaceBitrateOf(group.interfaceItem, "rx"))}</span>
              {ENABLE_SPARKLINES && <Sparkline values={group.interfaceItem?.rxSparkline ?? []} width={150} height={18} color="#66d9ef" strokeWidth={1.1} />}
            </span>
            <span className="interface-rate-row">
              <span className="interface-rate-label">TX</span>
              <span className="interface-rate-value">{formatBitrate(interfaceBitrateOf(group.interfaceItem, "tx"))}</span>
              {ENABLE_SPARKLINES && <Sparkline values={group.interfaceItem?.txSparkline ?? []} width={150} height={18} color="#f7c873" strokeWidth={1.1} />}
            </span>
          </span>
        </button>
      </div>
    );
  };

  const renderTruncatedRow = (row: Extract<FlatRow, { type: "truncated" }>) => {
    const className = row.depth === "flow" ? "flow-list-row flow-list-row-truncated stream-table-virtual-flow" : "stream-row stream-row-truncated stream-table-virtual-stream";
    return (
      <div className={className}>
        <span className="flow-main stream-main">
          <span className="flow-subtitle stream-subtitle">{row.label}</span>
        </span>
      </div>
    );
  };

  return (
    <div
      ref={tableRef}
      className={`stream-table ${overviewMode ? "overview-mode" : ""}`}
      onScroll={() => {
        scrollingRef.current = true;
        if (scrollRafRef.current === null) {
          scrollRafRef.current = window.requestAnimationFrame(() => {
            scrollRafRef.current = null;
            const root = tableRef.current;
            if (!root) return;
            setViewport((current) => {
              const next = { top: root.scrollTop, height: root.clientHeight || 640 };
              return current.top === next.top && current.height === next.height ? current : next;
            });
          });
        }
        if (scrollIdleTimerRef.current !== null) {
          window.clearTimeout(scrollIdleTimerRef.current);
        }
        scrollIdleTimerRef.current = window.setTimeout(() => {
          scrollingRef.current = false;
        }, 140);
      }}
    >
      {overviewMode && ENABLE_OVERVIEW_CHARTS && <StreamOverviewSummary streams={streams} />}
      {virtualRows.topPad > 0 ? <div style={{ height: virtualRows.topPad }} /> : null}
      {virtualRows.visible.map((row) => (
        <div key={row.key} className={`stream-table-virtual-item stream-table-virtual-item-${row.type}`} style={{ height: row.height }}>
          {row.type === "interface" ? renderInterfaceRow(row.group)
            : row.type === "proto" ? renderProtoRow(row.group)
              : row.type === "stream" ? renderStreamRow(row.stream)
                : row.type === "flow" ? (
                  <div className="stream-table-virtual-flow">
                    <FlowRow
                      streamKey={row.stream.streamKey}
                      flow={row.flow}
                      selected={row.flow.flowKey === selectedFlowKey}
                      overviewMode={overviewMode}
                      enableCharts={ENABLE_SPARKLINES}
                      onSelect={() => onSelectFlow(row.stream.streamKey, row.flow.flowKey)}
                    />
                  </div>
                )
                  : renderTruncatedRow(row)}
              </div>
      ))}
      {virtualRows.bottomPad > 0 ? <div style={{ height: virtualRows.bottomPad }} /> : null}
    </div>
  );
}

function InterfaceHeadroomGauge({ item }: { item?: InterfaceListItem }) {
  const usage = interfaceCombinedUsage(item);
  const headroom = usage !== undefined ? 1 - usage : undefined;
  return (
    <span className="interface-headroom">
      <SemiDonutGauge value={headroom} mode="headroom" size={54} />
      <span>
        <strong>{formatPercent(headroom)}</strong>
        <small>free</small>
      </span>
    </span>
  );
}

function SemiDonutGauge({ value, mode, size = 64 }: { value?: number; mode: "headroom" | "usage"; size?: number }) {
  const radius = 26;
import type { CSSProperties } from "react";
import type { InterfaceListItem, InterfaceMetricsResponse } from "../types/api";
import { MetricChart } from "./MetricChart";
import { Icon } from "./ui/Icon";
import { formatBitrate, formatNumber, formatRelativeTime } from "./format";

type InterfaceDetailPaneProps = {
  item: InterfaceListItem | null;
  metrics: InterfaceMetricsResponse | null;
  mode: "overview" | "detail";
  onChangeMode: (mode: "overview" | "detail") => void;
  onMinimizeWidth: () => void;
  onRestoreWidth: () => void;
  onMaximizeWidth: () => void;
  isWidthMinimized: boolean;
  isWidthRestored: boolean;
  isWidthMaximized: boolean;
  showWidthControls: boolean;
  embedded?: boolean;
};

export function InterfaceDetailPane({
  item,
  metrics,
  mode,
  onChangeMode,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
  isWidthMaximized,
  showWidthControls,
  embedded = false
}: InterfaceDetailPaneProps) {
  if (!item) {
    return <aside className="detail-pane empty-state">Select an interface or stream.</aside>;
  }

  return (
    <aside className={["detail-pane", "interface-detail-pane", mode === "overview" ? "graph-mode" : "", embedded ? "detail-pane-embedded" : ""].filter(Boolean).join(" ")}>
      {!embedded && <header className="pane-header detail-header detail-header-with-mode">
        <div className="detail-heading">
          <Icon className="pane-header-icon" name="detail" size={14} /><span className="kind-pill">NIC</span>
          <h2>{item.name}</h2>
          <p>{item.available ? "Available" : "Unavailable"} / {item.streamCount} stream{item.streamCount === 1 ? "" : "s"} / last seen {item.lastSeen ? formatRelativeTime(item.lastSeen) : "waiting"}</p>
        </div>
        <div className="detail-header-actions">
          {showWidthControls && (
            <div className="pane-width-controls" aria-label="Detail width controls">
              <button type="button" className={`size-button size-button-v size-button-left ${isWidthMaximized ? "active" : ""}`} onClick={onMaximizeWidth} aria-pressed={isWidthMaximized} title="Maximize detail pane"><Icon name="widthMaximize" size={16} /></button>
              <button type="button" className={`size-button size-button-v size-button-center ${isWidthRestored ? "active" : ""}`} onClick={onRestoreWidth} aria-pressed={isWidthRestored} title="Restore detail pane width"><Icon name="widthRestore" size={16} /></button>
              <button type="button" className={`size-button size-button-v size-button-right ${isWidthMinimized ? "active" : ""}`} onClick={onMinimizeWidth} aria-pressed={isWidthMinimized} title="Shrink detail pane"><Icon name="widthMinimize" size={16} /></button>
            </div>
          )}
          <div className="detail-mode-tabs" role="tablist" aria-label="NIC detail mode">
            <button className={mode === "overview" ? "active" : ""} onClick={() => onChangeMode("overview")} type="button">Overview</button>
            <button className={mode === "detail" ? "active" : ""} onClick={() => onChangeMode("detail")} type="button">Detail</button>
          </div>
        </div>
      </header>}

      <div className="detail-body">
        {mode === "overview" ? (
          <InterfaceOverview item={item} metrics={metrics} />
        ) : (
          <>
            <div className="overview-grid">
              <Stat label="RX Bitrate" value={formatBitrate(item.rxBitrate.value ?? item.rxBitrate.avg)} />
              <Stat label="TX Bitrate" value={formatBitrate(item.txBitrate.value ?? item.txBitrate.avg)} />
              <Stat label="Link" value={formatLinkSummary(item)} />
              <Stat label="Headroom" value={formatPercent(interfaceHeadroom(item))} />
              <Stat label="Streams" value={String(item.streamCount)} />
            </div>

            <BandwidthUsagePanel item={item} />

            <section className="stats-section">
              <h3>NIC Stats</h3>
              <div className="stats-grid">
                <Stat label="RX Packets" value={formatNumber(item.rx.packets.value ?? 0)} />
                <Stat label="TX Packets" value={formatNumber(item.tx.packets.value ?? 0)} />
                <Stat label="RX Drops" value={formatNumber(item.rx.dropped.value ?? 0)} />
                <Stat label="TX Drops" value={formatNumber(item.tx.dropped.value ?? 0)} />
                <Stat label="RX Errors" value={formatNumber(item.rx.errors.value ?? 0)} />
                <Stat label="TX Errors" value={formatNumber(item.tx.errors.value ?? 0)} />
              </div>
            </section>

            <MetricChart title="RX Bitrate" metric={metrics?.metrics["rx.bitrate"]} color="#66d9ef" />
            <MetricChart title="TX Bitrate" metric={metrics?.metrics["tx.bitrate"]} color="#f7c873" />

            <section className="metric-group">
              <h3>Packets / Drops / Errors</h3>
              <div className="chart-stack">
                <MetricChart title="RX Packets" metric={metrics?.metrics["rx.packets"]} height={150} color="#7fd4c7" />
                <MetricChart title="TX Packets" metric={metrics?.metrics["tx.packets"]} height={150} color="#d8b86d" />
                <MetricChart title="RX Dropped" metric={metrics?.metrics["rx.dropped"]} height={130} color="#d6b66f" />
                <MetricChart title="TX Dropped" metric={metrics?.metrics["tx.dropped"]} height={130} color="#cda866" />
                <MetricChart title="RX Errors" metric={metrics?.metrics["rx.errors"]} height={130} color="#d98b7f" />
                <MetricChart title="TX Errors" metric={metrics?.metrics["tx.errors"]} height={130} color="#c98278" />
              </div>
            </section>
          </>
        )}
      </div>
    </aside>
  );
}

function InterfaceOverview({ item, metrics }: { item: InterfaceListItem; metrics: InterfaceMetricsResponse | null }) {
  return (
    <div className="graph-mode-layout interface-overview-layout">
      <section className="graph-summary-band">
        <Stat label="RX" value={formatBitrate(item.rxBitrate.value ?? item.rxBitrate.avg)} />
        <Stat label="TX" value={formatBitrate(item.txBitrate.value ?? item.txBitrate.avg)} />
        <Stat label="Headroom" value={formatPercent(interfaceHeadroom(item))} />
        <Stat label="Link" value={formatLinkSummary(item)} />
        <Stat label="Drops" value={formatNumber((item.rx.dropped.value ?? 0) + (item.tx.dropped.value ?? 0))} />
        <Stat label="Errors" value={formatNumber((item.rx.errors.value ?? 0) + (item.tx.errors.value ?? 0))} />
      </section>
      <BandwidthUsagePanel item={item} compact />
      <section className="graph-card-grid interface-overview-grid">
        <MetricChart title="RX Utilization" metric={metrics?.metrics["rx.utilization"]} height={108} compact color="#66d9ef" />
        <MetricChart title="TX Utilization" metric={metrics?.metrics["tx.utilization"]} height={108} compact color="#f7c873" />
        <MetricChart title="RX Bitrate" metric={metrics?.metrics["rx.bitrate"]} height={126} compact color="#66d9ef" />
        <MetricChart title="TX Bitrate" metric={metrics?.metrics["tx.bitrate"]} height={126} compact color="#f7c873" />
        <MetricChart title="RX Packets" metric={metrics?.metrics["rx.packets"]} height={108} compact color="#7fd4c7" />
        <MetricChart title="TX Packets" metric={metrics?.metrics["tx.packets"]} height={108} compact color="#d8b86d" />
        <MetricChart title="RX Dropped" metric={metrics?.metrics["rx.dropped"]} height={108} compact color="#d6b66f" />
        <MetricChart title="TX Dropped" metric={metrics?.metrics["tx.dropped"]} height={108} compact color="#cda866" />
        <MetricChart title="RX Errors" metric={metrics?.metrics["rx.errors"]} height={108} compact color="#d98b7f" />
        <MetricChart title="TX Errors" metric={metrics?.metrics["tx.errors"]} height={108} compact color="#c98278" />
      </section>
    </div>
  );
}

function BandwidthUsagePanel({ item, compact = false }: { item: InterfaceListItem; compact?: boolean }) {
  const rxUsage = item.rxRate?.utilization;
  const txUsage = item.txRate?.utilization;
  const speed = item.link?.speedMbps ? formatLinkSpeed(item.link.speedMbps) : "unknown";
  return (
    <section className={`bandwidth-panel ${compact ? "compact" : ""}`}>
      <div className="bandwidth-panel-header">
        <h3>Link Capacity</h3>
        <span>{speed} / {item.link?.duplex ?? "duplex unknown"} / {item.link?.operstate ?? "state unknown"}</span>
      </div>
      <div className="bandwidth-gauge-grid">
        <BandwidthGauge label="RX" usage={rxUsage} bitrate={item.rxRate?.bitrateBps ?? item.rxBitrate.value ?? item.rxBitrate.avg} headroom={item.rxRate?.headroomBps} color="#66d9ef" />
