        if (cancelled) return;
        setSelectedStream(stream);
        setSelectedMetrics(metrics);
      });
    };
    load();
    if (selectedMetricsRange === "5m" || selectedTimeSec !== null) {
      return () => {
        cancelled = true;
      };
    }
    const timer = window.setInterval(load, 10000);
    return () => {
      cancelled = true;
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [selectedStreamKey, selectedMetricsRange, selectedTimeSec, paused]);

  useEffect(() => {
    if (selectedInterfaceKey === null) {
      setSelectedInterfaceMetrics(null);
      return;
    }

    if (paused && selectedTimeSec === null) return;
    let cancelled = false;
    const load = () => {
      const query = metricsQueryForRange(selectedMetricsRange, selectedTimeSec);
      void getInterfaceMetricsByKey(selectedInterfaceKey, query).then((metrics) => {
        if (!cancelled) setSelectedInterfaceMetrics(metrics);
      }).catch(() => {
        if (!cancelled) setSelectedInterfaceMetrics(null);
      });
      socket?.close();
    };
  }, []);

  useEffect(() => {
    const socket = socketRef.current;
    if (socket?.readyState === WebSocket.OPEN) {
      socket.send(JSON.stringify({ type: "stream:subscribe", streamKey: selectedStreamKey }));
    }
  }, [selectedStreamKey]);

  useEffect(() => {
    const resumed = previousPausedRef.current && !paused;
    previousPausedRef.current = paused;
    if (!resumed) return;

    let cancelled = false;
    void Promise.all([
      getBootstrap(),
      selectedStreamKeyRef.current ? getStream(selectedStreamKeyRef.current) : Promise.resolve(null),
      selectedStreamKeyRef.current ? getStreamMetrics(selectedStreamKeyRef.current, metricsQueryForRange(selectedMetricsRange)) : Promise.resolve(null),
      selectedInterfaceKeyRef.current ? getInterfaceMetricsByKey(selectedInterfaceKeyRef.current) : Promise.resolve(null)
    ]).then(([bootstrap, stream, metrics, interfaceMetrics]) => {
      if (cancelled) return;
      setStreams(bootstrap.streams);
      setInterfaces(bootstrap.interfaces);
      setSummary(bootstrap.summary);
      updateLiveSummary(bootstrap.summary);
      if (!eventsLoadedRef.current) setEvents(bootstrap.events);
      setSelectedStream(stream);
      setSelectedMetrics(metrics);
      setSelectedInterfaceMetrics(interfaceMetrics);
    });

    return () => {
      cancelled = true;
    };
  }, [paused, selectedMetricsRange]);

  const selectedListItem = useMemo(
    () => streams.find((stream) => stream.streamKey === selectedStreamKey) ?? null,
    [streams, selectedStreamKey]
  );

  const selectedInterface = useMemo(
    () => interfaces.find((item) => item.key === selectedInterfaceKey) ?? null,
    [interfaces, selectedInterfaceKey]
  );

  return {
    streams,
    interfaces,
    timeline,
    timelineWindow,
    timelineAvailable,
    timelineSource,
  }
  return `stream:${row.streamKey}`;
}

function formatTimeTravel(epochSec: number) {
  return new Date(epochSec * 1000).toLocaleString(undefined, { hour12: false });
}

function standaloneViewFromPath(pathname: string): StandaloneView {
  switch (pathname.replace(/\/+$/, "")) {
    case "/view/streams":
      return "streams";
    case "/view/timeline":
      return "timeline";
    case "/view/events":
      return "events";
    case "/view/detail":
      return "detail";
    default:
      return null;
  }
}

function dashboardCellTextParam(cell: DashboardCell, key: string) {
  const value = cell.params?.[key];
  return typeof value === "string" ? value : "";
}

function dashboardDetailMode(cell: DashboardCell): DetailMode {
  return dashboardCellTextParam(cell, "detailMode") === "detail" ? "detail" : "overview";
}

function dashboardEventsTab(cell: DashboardCell): EventLogTab {
  return dashboardCellTextParam(cell, "eventsTab") === "selected" ? "selected" : "all";
}

